const rows = $input.all().map(i => i.json).filter(r => r.order_id);
const num = v => parseFloat(v) || 0;
const day = d => String(d).slice(0, 10);

// DEMO: report on the latest date in the data.
// For production, replace with yesterday's date:
// const reportDate = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
const reportDate = rows.map(r => day(r.order_date)).sort().pop();

const prior = new Date(reportDate);
prior.setDate(prior.getDate() - 1);
const priorDate = prior.toISOString().slice(0, 10);

const valid = r => r.status !== 'refunded';
const byDay = d => rows.filter(r => day(r.order_date) === d);
const revenue = list => list.filter(valid).reduce((s, r) => s + num(r.total), 0);
const round = v => Math.round(v * 100) / 100;

const today = byDay(reportDate);
const yesterday = byDay(priorDate);
const revToday = revenue(today);
const revYesterday = revenue(yesterday);

// trailing 7-day average (the 7 days before the report date)
const sevenDays = [];
for (let i = 1; i <= 7; i++) {
  const d = new Date(reportDate); d.setDate(d.getDate() - i);
  sevenDays.push(revenue(byDay(d.toISOString().slice(0, 10))));
}
const avg7 = sevenDays.reduce((a, b) => a + b, 0) / 7;

// top products and categories for the day
const tally = (list, key) => {
  const t = {};
  list.filter(valid).forEach(r => { t[r[key]] = (t[r[key]] || 0) + num(r.total); });
  return Object.entries(t).sort((a, b) => b[1] - a[1]).map(([name, total]) => ({ name, total: round(total) }));
};

const refunds = today.filter(r => r.status === 'refunded').length;
const orderCount = today.filter(valid).length;

return [{
  json: {
    report_date: reportDate,
    revenue: round(revToday),
    orders: orderCount,
    avg_order_value: orderCount ? round(revToday / orderCount) : 0,
    refund_rate: today.length ? round((refunds / today.length) * 100) : 0,
    prior_day_revenue: round(revYesterday),
    change_vs_prior_day_pct: revYesterday ? round(((revToday - revYesterday) / revYesterday) * 100) : null,
    avg_7day_revenue: round(avg7),
    change_vs_7day_avg_pct: avg7 ? round(((revToday - avg7) / avg7) * 100) : null,
    top_products: tally(today, 'product').slice(0, 3),
    categories: tally(today, 'category')
  }
}];

// n8n Code node: JavaScript, mode "Run Once for Each Item". Name: Build Email
const m = $('Compute Metrics').item.json;
const ai = $json.output;

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = v => '$' + Number(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const pct = v => (v === null || v === undefined) ? 'n/a' : (v > 0 ? '+' : '') + v + '%';
const color = v => (v === null || v === undefined) ? '#666666' : (v < 0 ? '#c0392b' : '#1e8449');

const kpi = (label, value, sub, subColor) => `
  <td style="padding:12px;background:#f6f7f9;border-radius:6px;text-align:center;width:25%;">
    <div style="font-size:12px;color:#666666;">${label}</div>
    <div style="font-size:20px;font-weight:bold;color:#111111;margin:4px 0;">${value}</div>
    <div style="font-size:11px;color:${subColor};">${sub}</div>
  </td>`;

const list = arr => (arr || []).map(x => `<li style="margin-bottom:6px;">${esc(x)}</li>`).join('');
const rank = arr => (arr || []).map(x => `<li>${esc(x.name)}: ${money(x.total)}</li>`).join('');

const html = `
<div style="font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:auto;color:#222222;">
  <h2 style="margin-bottom:4px;">${esc(ai.headline)}</h2>
  <div style="color:#666666;font-size:13px;margin-bottom:16px;">Daily report for ${esc(m.report_date)}</div>

  <table role="presentation" width="100%" cellspacing="8" style="border-collapse:separate;margin-bottom:12px;">
    <tr>
      ${kpi('Revenue', money(m.revenue), pct(m.change_vs_7day_avg_pct) + ' vs 7-day avg', color(m.change_vs_7day_avg_pct))}
      ${kpi('Orders', m.orders, 'prior day ' + money(m.prior_day_revenue), '#666666')}
      ${kpi('Avg order', money(m.avg_order_value), '', '#666666')}
      ${kpi('Refund rate', m.refund_rate + '%', '', '#666666')}
    </tr>
  </table>

  <p style="line-height:1.5;">${esc(ai.summary)}</p>

  <h3 style="margin-bottom:6px;">What stands out</h3>
  <ul style="padding-left:20px;line-height:1.4;">${list(ai.observations)}</ul>

  <h3 style="margin-bottom:6px;">Worth checking</h3>
  <ul style="padding-left:20px;line-height:1.4;">${list(ai.actions)}</ul>

  <h3 style="margin-bottom:6px;">Top products</h3>
  <ol style="padding-left:20px;">${rank(m.top_products)}</ol>

  <h3 style="margin-bottom:6px;">By category</h3>
  <ul style="padding-left:20px;">${rank(m.categories)}</ul>

  <p style="font-size:11px;color:#999999;margin-top:24px;">Figures are calculated from the Orders sheet. The summary is AI-written and only uses those figures.</p>
</div>`;

const subject = `Daily report ${m.report_date}: ${money(m.revenue)} (${pct(m.change_vs_7day_avg_pct)} vs 7-day avg)`;

return { json: { subject, html } };
